/* @lc app=leetcode id=1514 lang=kotlin */ class Solution { fun maxProbability(n: Int, edges: Array<IntArray>, succProb: DoubleArray, start_node: Int, end_node: Int): Double = edges.indices.flatMap { i -> listOf(edges[i][0] to (edges[i][1] to succProb[i]), edges[i][1] to (edges[i][0] to succProb[i])) }.groupBy({ it.first }, { it.second }).let { g -> DoubleArray(n).also { it[start_node] = 1.0 }.let { d -> java.util.PriorityQueue<Pair<Double, Int>>(compareByDescending { it.first }).also { it.add(1.0 to start_node) }.let { pq -> generateSequence { pq.poll() }.filter { (p, u) -> p == d[u] }.forEach { (p, u) -> g[u].orEmpty().filter { (v, w) -> p * w > d[v] }.forEach { (v, w) -> pq.add(p * w to v).also { d[v] = p * w } } }.let { d[end_node] } } } } }